import React, { useState } from 'react';
import './Login.css';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = (e) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Please fill in all fields.');
      return;
    }
    // Login API Call Logic Here
    console.log({ email, password, rememberMe });
  };

  return (
    <div className="dark-landing-container">
      {/* Top Navigation */}
      <nav className="dark-navbar">
        <div className="dark-brand">
          <span className="brand-icon">🎓</span>
          <span className="brand-title">CampusSetu</span>
        </div>
        <div className="nav-links">
          <a href="#home" className="active">Home</a>
          <a href="#features">Features</a>
          <a href="#about">About</a>
          <a href="#benefits">Benefits</a>
          <a href="#contact">Contact</a>
        </div>
        <div className="nav-badge">🔒 Secure Campus Portal</div>
      </nav>

      {/* Main Hero Section */}
      <div className="hero-section">
        {/* Left Side: Text & Feature Cards */}
        <div className="hero-content">
          <h1 className="hero-title">
            Smarter Campus. <br />
            <span className="highlight-text">Better Tomorrow.</span>
          </h1>
          <p className="hero-description">
            A unified platform to manage complaints, maintenance, lost & found, 
            lab bookings, announcements, and campus services — all in one place.
          </p>

          <div className="hero-actions">
            <button className="btn-primary-orange">Login to Continue →</button>
            <button className="btn-secondary-outline">Explore Features →</button>
          </div>

          {/* Quick Feature Grid */}
          <div className="feature-grid">
            <div className="feature-card">
              <span className="feature-icon">💬</span>
              <h4>Overview</h4>
              <p>Report and track campus issues easily</p>
            </div>
            <div className="feature-card active-card">
              <span className="feature-icon">🛠️</span>
              <h4>Manage Complaints</h4>
              <p>Raise requests and get quick status updates</p>
            </div>
            <div className="feature-card">
              <span className="feature-icon">🎁</span>
              <h4>Manage Booking</h4>
              <p>Book labs and other campus facilities with ease</p>
            </div>
            <div className="feature-card">
              <span className="feature-icon">📢</span>
              <h4>Announce</h4>
              <p>Stay updated with important campus news</p>
            </div>
          </div>
        </div>

        
          </div>
        </div>
      
  );
};

export default Login;
